public class InfyGoUserDetails implements UserDetails {
	private List<String> userRoles;
	private User user;

	public InfyGoUserDetails(User user, List<String> userRoles) {
		this.user = user;
		this.userRoles = userRoles;
	}

	@Override
	public Collection<? extends GrantedAuthority> getAuthorities() {
		String roles = StringUtils.collectionToCommaDelimitedString(userRoles);
		return AuthorityUtils.commaSeparatedStringToAuthorityList(roles);
	}
	@Override public String getUsername() { return user.getUserId(); }
	@Override public String getPassword() { return user.getPassword(); }
	@Override public boolean isAccountNonExpired() { return true; }
	@Override public boolean isAccountNonLocked() { return true; }
	@Override public boolean isCredentialsNonExpired() { return true; }
	@Override public boolean isEnabled() { return true; }
}

@Service
public class InfyGoUserDetailsService implements UserDetailsService {
	@Autowired private UserRepository userRepository;
	@Autowired private PasswordEncoder passwordEncoder;

	@Override
	public UserDetails loadUserByUsername(String username) {
		UserEntity entity = userRepository.findByName(username);
		if (entity == null) throw new UsernameNotFoundException(username);

		User user = new User();
		user.setName(entity.getName());
		user.setPassword(passwordEncoder.encode(entity.getPassword()));
		user.setUserId(entity.getUserId());

		List<String> roles = Arrays.asList("USER");
		return new InfyGoUserDetails(user, roles);
	}
}

@Configuration
@Order(SecurityProperties.BASIC_AUTH_ORDER)
public class SecurityConfig extends WebSecurityConfigurerAdapter {

	@Autowired private InfyGoUserDetailsService userDetailsService;

	@Autowired
	public void configAuthentication(AuthenticationManagerBuilder auth) throws Exception {
		auth.userDetailsService(userDetailsService);
	}

	@Override
	protected void configure(HttpSecurity http) throws Exception {
		http
			.authorizeRequests()
				.antMatchers("/", "/login", "/register", "/imgs/**").permitAll()
				.anyRequest().authenticated()
			.and()
			.formLogin()
				.loginPage("/login")
				.defaultSuccessUrl("/flights", true)
				.permitAll()
			.and()
			.logout().permitAll();
	}

	@Bean
	public PasswordEncoder passwordEncoder() {
		return new BCryptPasswordEncoder();
	}
}

public void updateFlight(String flightId, String noOfSeats) throws InfyGoBootException {
	FlightEntity flight = flightsRepository.getOne(flightId);
	if (flight == null) {
		throw new InfyGoBootException("No flight for the given details");
	} else {
		int count = flight.getSeatCount() - Integer.valueOf(noOfSeats);
		flight.setSeatCount(count);
		flightsRepository.saveAndFlush(flight);
	}
}

@Autowired
public void configAuthentication(AuthenticationManagerBuilder auth) throws Exception {
	auth.inMemoryAuthentication()
	    .withUser("C1001").password(passwordEncoder().encode("Jack1234")).roles("USER");
}

